function model(p) {
  // Simplified Git story: a feature branch, an optional urgent hotfix on main, a pull request, a review and a merge.
  // People, ids and times are fictional. An id is a short hash of message, parents, author and commit time,
  // so a replayed (rebased) commit always gets a new id, as in real Git.
  const hotfix = Math.round(p.hotfix) === 1, sameFile = Math.round(p.sameFile) === 1;
  const style = ['merge', 'rebase', 'squash'][Math.max(0, Math.min(2, Math.round(p.mergeStyle)))];
  const conflict = hotfix && sameFile;
  const people = {
    priya: { name: 'Priya', role: 'developer', color: '#b4530f' }, marco: { name: 'Marco', role: 'teammate', color: '#0f766e' },
    dana: { name: 'Dana', role: 'reviewer', color: '#2b59c3' }, github: { name: 'GitHub', role: 'repository', color: '#5b6475' }
  };
  const hash = s => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return (h >>> 0).toString(16).padStart(8, '0').slice(0, 7); };
  const commits = [], events = [], notes = [], byId = {};
  let t = 0, col = 0, pr = 'None';
  const add = (msg, author, lane, parents, files, adds, clock, extra) => {
    const c = Object.assign({ id: hash(msg + '|' + parents.join(',') + '|' + author + '|' + clock), msg, author, lane, clock, col: col++, born: +t.toFixed(2), ghostAt: null, moveAt: null, fromLane: null }, extra || {});
    if (parents.length) c.parents = parents; // the root commit has no parents key
    if (files.length) c.files = files;
    if (adds.length) c.adds = adds;
    commits.push(c); byId[c.id] = c; return c;
  };
  const ev = (kind, dur, actor, clock, caption, extra) => { const e = Object.assign({ i: events.length, kind, t: +t.toFixed(2), actor, clock, caption, pr }, extra || {}); events.push(e); t += dur; return e; };
  const replay = (base, lane, clock) => { let prev = base; return feat.map(o => (prev = add(o.msg, o.author, lane, [prev.id], o.files || [], o.adds || [], clock, { replayOf: o.id }))); };

  const c0 = add('Initial project', 'Marco', 'main', [], ['README.md'], ['base'], 'Mon 16:20');
  const c1 = add('Add report page', 'Priya', 'main', [c0.id], ['src/report.js'], ['report'], 'Mon 17:05');
  ev('start', 1.2, 'github', 'Tue 09:00', 'main is the branch the team ships from, so it must always work. It holds two commits so far.');
  ev('branch', 1.4, 'priya', 'Tue 09:10', 'Priya creates feature/csv-export from main to build a CSV export. Her work stays off main until it is ready.', { commit: c1.id });
  const f1 = add('Add export button', 'Priya', 'feature', [c1.id], ['src/report.js'], ['export-button'], 'Tue 10:05');
  ev('commit', 1.3, 'priya', f1.clock, 'Priya commits "Add export button" on her branch. main does not change at all.', { commit: f1.id });
  let h = null;
  if (hotfix) {
    const file = sameFile ? 'src/dates.js' : 'src/invoice.js';
    h = add('Fix invoice date format', 'Marco', 'main', [c1.id], [file], ['date-fix'], 'Tue 10:40');
    ev('hotfix', 1.8, 'marco', h.clock, 'Meanwhile invoices show the wrong date in production. Marco ships an urgent fix straight to main, in ' + file + '.', { commit: h.id });
  }
  const f2 = add('Build CSV from table rows', 'Priya', 'feature', [f1.id], ['src/export.js'], ['csv-rows'], 'Tue 11:30');
  ev('commit', 1.2, 'priya', f2.clock, 'Priya keeps working on her branch: "Build CSV from table rows".', { commit: f2.id });
  const f3 = add('Format dates in CSV', 'Priya', 'feature', [f2.id], ['src/dates.js'], ['csv-dates'], 'Tue 13:15');
  ev('commit', 1.2, 'priya', f3.clock, '"Format dates in CSV" edits src/dates.js' + (conflict ? ', the same file Marco just fixed on main.' : (hotfix ? '. Marco\'s fix touched a different file.' : '.')), { commit: f3.id });
  pr = 'Open';
  notes.push({ commit: f3.id, from: +t.toFixed(2), to: +(t + 1.6).toFixed(2), text: 'PR #42 opened', tone: 'accent' });
  ev('pr', 1.6, 'priya', 'Tue 13:30', 'Priya opens pull request #42: merge feature/csv-export into main. It lists her 3 commits and every changed line.');
  pr = 'Changes requested';
  notes.push({ commit: f3.id, from: +t.toFixed(2), to: +(t + 2.9).toFixed(2), text: 'Dana: handle empty tables', tone: 'accent' });
  ev('review', 1.6, 'dana', 'Tue 14:20', 'Dana reviews the pull request and comments: "An empty table exports a blank file. Please handle it."');
  const f4 = add('Handle empty tables', 'Priya', 'feature', [f3.id], ['src/export.js'], ['empty-tables'], 'Tue 15:05');
  ev('commit', 1.3, 'priya', f4.clock, 'Priya answers the review with one more commit, "Handle empty tables". The pull request updates itself.', { commit: f4.id });
  pr = 'Approved';
  const approveT = +t.toFixed(2);
  ev('approve', 1.2, 'dana', 'Tue 15:40', 'Dana approves pull request #42. Every change was reviewed before it can reach main.');
  const feat = [f1, f2, f3, f4];
  let tip = f4, mainTip = h || c1, replays = null, conflictInfo = null;
  if (conflict) {
    pr = 'Conflict';
    conflictInfo = { a: h.id, b: f3.id, file: 'src/dates.js', line: 12, found: +t.toFixed(2), resolved: 0 };
    ev('conflict', 1.8, 'github', 'Tue 15:45', 'Conflict! Marco\'s hotfix and Priya\'s "Format dates in CSV" both changed line 12 of src/dates.js. Git will not guess.');
    conflictInfo.resolved = +t.toFixed(2);
    notes.push({ commit: f3.id, from: conflictInfo.found, to: conflictInfo.resolved, text: 'Conflict: src/dates.js line 12', tone: 'warn' });
    pr = 'Ready to merge';
    if (style === 'rebase') {
      replays = replay(h, 'feature', 'Tue 16:10');
      feat.forEach(c => { c.ghostAt = conflictInfo.resolved; });
      ev('resolve', 1.8, 'priya', 'Tue 16:10', 'Priya rebases her branch onto the new main and fixes the clash as Git replays her 4 commits. Each copy gets a new id.');
    } else {
      tip = add('Merge main into feature/csv-export', 'Priya', 'feature', [f4.id, h.id], ['src/dates.js'], ['resolution'], 'Tue 16:10');
      ev('resolve', 1.8, 'priya', tip.clock, 'Priya merges main into her branch, keeps both date changes in src/dates.js and commits the fix. Now it merges cleanly.', { commit: tip.id });
    }
  }
  const mergeT = +t.toFixed(2);
  notes.push({ commit: f4.id, from: approveT, to: conflict ? conflictInfo.found : mergeT, text: 'Approved by Dana', tone: 'good' });
  pr = 'Merged';
  let finalTip, caption;
  if (style === 'merge') {
    finalTip = add('Merge pull request #42', 'Dana', 'main', [mainTip.id, tip.id], [], [], 'Tue 16:15', { merge: true });
    caption = 'Dana clicks "Create a merge commit". New commit ' + finalTip.id + ' has two parents: ' + mainTip.id + ' on main and ' + tip.id + ' from the branch.';
  } else if (style === 'rebase') {
    if (!replays) { replays = replay(mainTip, 'main', 'Tue 16:15'); feat.forEach(c => { c.ghostAt = mergeT; }); }
    replays.forEach(c => { c.fromLane = 'feature'; c.lane = 'main'; c.moveAt = +(mergeT + 0.4).toFixed(2); });
    finalTip = replays[replays.length - 1];
    caption = '"Rebase and merge": Priya\'s 4 commits now sit after ' + (hotfix ? 'the hotfix' : mainTip.id) + ' as new commits with new ids, and main moves up to them. One straight line.';
  } else {
    const folded = conflict ? feat.concat([tip]) : feat;
    const uniq = a => a.filter((x, i) => a.indexOf(x) === i);
    finalTip = add('Add CSV export (#42)', 'Priya', 'main', [mainTip.id], uniq([].concat(...folded.map(c => c.files || []))), uniq([].concat(...folded.map(c => c.adds || []))), 'Tue 16:15', { squashOf: folded.map(c => c.id) });
    caption = '"Squash and merge": all ' + folded.length + ' branch commits are folded into one new commit, ' + finalTip.id + ', on main.';
  }
  notes.push({ commit: finalTip.id, from: mergeT, to: 99, text: 'PR #42 merged', tone: 'good' });
  ev('merge', 2.2, 'dana', 'Tue 16:15', caption, { commit: finalTip.id });
  const delT = +t.toFixed(2);
  if (style === 'squash') commits.forEach(c => { if (c.lane === 'feature') c.ghostAt = delT; });
  ev('delete', 1.6, 'priya', 'Tue 16:16', 'Priya deletes feature/csv-export. ' + ({
    merge: 'Its commits live on in main through the merge commit.',
    rebase: 'The old commits are no longer on any branch; main has the replayed copies.',
    squash: 'Its separate commits are no longer on any branch; main keeps the single squashed commit.'
  })[style]);
  const duration = +(t + 1.0).toFixed(2);

  // Final history of main: everything reachable from the tip, oldest first.
  const seen = new Set(), stack = [finalTip.id];
  while (stack.length) { const id = stack.pop(); if (seen.has(id)) continue; seen.add(id); (byId[id].parents || []).forEach(x => stack.push(x)); }
  const mainHistory = commits.filter(c => seen.has(c.id)).map(c => ({ id: c.id, msg: c.msg, parents: (c.parents || []).length }));
  const name = { merge: 'Merge commit', rebase: 'Rebase', squash: 'Squash' }[style];
  const summary = name + ': main has ' + mainHistory.length + ' commits with ' + (hotfix ? 'the hotfix and ' : '') + 'the CSV export' +
    ({ merge: ', joined by merge commit ' + finalTip.id + ' with two parents.', rebase: ', in one straight line of replayed commits.', squash: ', which arrived as one commit, ' + finalTip.id + '.' })[style] +
    (conflict ? ' A conflict in src/dates.js was resolved first.' : '');
  return {
    hotfix, sameFile, style, conflict, conflictInfo, people, commits, events, notes,
    hotfixId: h ? h.id : null, featureIds: feat.map(c => c.id), replayIds: replays ? replays.map(c => c.id) : null,
    forkId: c1.id, tipId: finalTip.id, mergeT, deleteT: delT, branchT: events[1].t,
    mainHistory, columns: col, duration, markers: events.map(e => e.t), summary
  };
}

checkCode:
function check(p) {
  const m = model(p), byId = {};
  m.commits.forEach(c => { byId[c.id] = c; });
  const ps = c => c.parents || [];
  // DAG: unique ids, every parent exists, no cycles (depth-first search with colours)
  const unique = Object.keys(byId).length === m.commits.length;
  const parentsExist = m.commits.every(c => ps(c).every(x => byId[x]));
  const state = {}; let cyclic = false;
  const visit = id => { if (state[id] === 2 || cyclic) return; if (state[id] === 1) { cyclic = true; return; } state[id] = 1; ps(byId[id]).forEach(x => byId[x] && visit(x)); state[id] = 2; };
  m.commits.forEach(c => visit(c.id));
  const hist = m.mainHistory, inMain = new Set(hist.map(c => c.id)), tip = byId[m.tipId];
  let styleOk, styleText;
  if (m.style === 'merge') {
    styleOk = ps(tip).length === 2 && m.featureIds.every(id => inMain.has(id));
    styleText = 'merge commit ' + tip.id + ' has ' + ps(tip).length + ' parents';
  } else if (m.style === 'rebase') {
    const base = m.hotfixId || m.forkId, r = m.replayIds || [];
    const linear = hist.every(c => c.parents <= 1);
    const replayed = r.length === m.featureIds.length && ps(byId[r[0]])[0] === base && r.every(id => !m.featureIds.includes(id) && inMain.has(id)) && m.featureIds.every(id => !inMain.has(id));
    styleOk = linear && replayed;
    styleText = (linear ? 'linear history, ' : 'not linear, ') + r.length + ' commits replayed after ' + base + ' with new ids';
  } else {
    const added = hist.filter(c => byId[c.id].born >= m.mergeT);
    styleOk = added.length === 1 && added[0].id === tip.id && ps(tip).length === 1 && m.featureIds.every(id => !inMain.has(id));
    styleText = added.length + ' new commit on main (' + tip.id + ')';
  }
  const hasConflict = m.events.some(e => e.kind === 'conflict');
  const conflictOk = hasConflict === (Math.round(p.hotfix) === 1 && Math.round(p.sameFile) === 1);
  const adds = new Set([].concat(...hist.map(c => byId[c.id].adds || [])));
  const need = ['export-button', 'csv-rows', 'csv-dates', 'empty-tables'].concat(m.hotfix ? ['date-fix'] : []);
  const contentOk = need.every(k => adds.has(k));
  return {
    pass: unique && parentsExist && !cyclic && styleOk && conflictOk && contentOk,
    detail: m.commits.length + ' commits form an acyclic graph' + (parentsExist ? ' with every parent present' : ' with a missing parent') + '; ' + styleText +
      '; ' + (hasConflict ? '1 conflict' : 'no conflict') + (conflictOk ? ' as expected' : ' (wrong)') + '; main ends with ' + hist.length + ' commits holding ' + need.filter(k => adds.has(k)).length + ' of ' + need.length + ' required changes.'
  };
}
